export type Dic = typeof es

// Traducción de los paquetes de folios. Vienen de la BD (editables por el admin)
// en español, así que traducimos por frase conocida y, si el admin escribe algo
// personalizado, se muestra tal cual (fallback). Los NOMBRES de plan son marca:
// no se traducen.
const PAQUETE_TR: Record<string, { en: string; pt: string; fr: string }> = {
  // descripciones
  'Para comenzar a cotizar': { en: 'To start quoting', pt: 'Para começar a orçar', fr: 'Pour commencer à deviser' },
  'Para ventas constantes': { en: 'For steady sales', pt: 'Para vendas constantes', fr: 'Pour des ventes régulières' },
  'Para equipos de alto volumen': { en: 'For high-volume teams', pt: 'Para equipes de alto volume', fr: 'Pour les équipes à fort volume' },
  // beneficios
  'PDFs personalizados': { en: 'Custom PDFs', pt: 'PDFs personalizados', fr: 'PDF personnalisés' },
  'WhatsApp y email': { en: 'WhatsApp and email', pt: 'WhatsApp e e-mail', fr: 'WhatsApp et e-mail' },
  'Sin fecha de caducidad': { en: 'No expiration date', pt: 'Sem data de validade', fr: 'Sans date d’expiration' },
  'Todo lo de Emprende': { en: 'Everything in Emprende', pt: 'Tudo do Emprende', fr: 'Tout d’Emprende' },
  'Ahorra por cotización': { en: 'Save per quote', pt: 'Economize por orçamento', fr: 'Économisez par devis' },
  'Soporte prioritario': { en: 'Priority support', pt: 'Suporte prioritário', fr: 'Support prioritaire' },
  'Todo lo de Negocio': { en: 'Everything in Negocio', pt: 'Tudo do Negocio', fr: 'Tout de Negocio' },
  'Mejor precio por folio': { en: 'Best price per credit', pt: 'Melhor preço por crédito', fr: 'Meilleur prix par crédit' },
  'Uso multiusuario': { en: 'Multi-user access', pt: 'Acesso multiusuário', fr: 'Accès multi-utilisateurs' },
  'API para integraciones': { en: 'API for integrations', pt: 'API para integrações', fr: 'API pour intégrations' },
}

// Traduce un texto de paquete al idioma activo (fallback: el texto original).
export function trPaquete(texto: string | null | undefined): string {
  if (!texto) return ''
  const lang = i18n.language?.split('-')[0]
  if (!lang || lang === 'es') return texto
  const t = PAQUETE_TR[texto]
  return t ? (t as Record<string, string>)[lang] ?? texto : texto
}

// Solo el español va en el bundle principal; inglés, portugués y francés se
// descargan al elegirlos (o si el navegador los pide).
const CARGADORES: Record<string, () => Promise<{ default: Dic }>> = {
  en: () => import('./idiomas/en'),
  pt: () => import('./idiomas/pt'),
  fr: () => import('./idiomas/fr'),
}
async function cargarIdioma(lng?: string) {
  const code = lng?.split('-')[0] ?? ''
  if (!CARGADORES[code] || i18n.hasResourceBundle(code, 'translation')) return
  try {
    const mod = await CARGADORES[code]()
    i18n.addResourceBundle(code, 'translation', mod.default, true, true)
  } catch { /* sin red: se queda el español (fallback) */ }
}

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources: { es: { translation: es } },
    partialBundledLanguages: true,
    fallbackLng: 'es',
    supportedLngs: ['es', 'en', 'pt', 'fr'],
    interpolation: { escapeValue: false },
    detection: { order: ['localStorage', 'navigator'], caches: ['localStorage'], lookupLocalStorage: 'cotizago_idioma' },
    // Re-renderiza cuando llega el diccionario descargado.
    react: { bindI18nStore: 'added' },
  })

cargarIdioma(i18n.language)
i18n.on('languageChanged', cargarIdioma)

export default i18n
